function SSNote(){const e=document.getElementById('ss-mode-note');if(!e)return;const n={RFI:'首次開池',DEFEND:'面對開池',FACING_3BET:'面對再加注',ALL_STREET:'翻牌後探索',PUSH_FOLD:'單挑SB Push/Fold',CUSTOM:'自訂練習',REVIEW:'錯題複習'},m=state.currentMode;e.innerHTML=`<div class="eyebrow">訓練 / ${n[m]||m}</div><h1>${n[m]||m}</h1><p>${m==='ALL_STREET'?'未經驗證的策略不計分。底池含待跟注下注，SPR採該下注前時點。':m==='PUSH_FOLD'?'限定單挑SB參考，不適用多人、ICM或完整limp/raise策略。':'分數表示符合參考資料的可接受動作，不等於完整實戰能力。'}</p><a class="link-button" href="learn.html?module=${m==='ALL_STREET'?6:2}">回看相關教學 →</a>`}const SSChange=window.changeMode;window.changeMode=function(...a){const r=SSChange(...a);SSNote();return r};window.toggleInfoModal=(p='rules')=>SSCommon.open(p==='glossary'?'glossary':'rules');window.openGlossaryTerm=slug=>SSCommon.open('glossary',slug);openGlossaryTerm=window.openGlossaryTerm;window.openDonateModal=window.openSupportModal=()=>SSCommon.open('support');window.openAboutModal=()=>SSCommon.open('settings');window.openFeedbackModal=()=>SSCommon.open('feedback');window.setSupportPage=p=>SSCommon.open(p==='about'?'settings':p==='feedback'?'feedback':'support');document.addEventListener('DOMContentLoaded',()=>{const e=document.createElement('section');e.className='mode-intro';e.id='ss-mode-note';document.getElementById('practice-panel').prepend(e);SSNote();for(const t of Object.values(I18N)){t.statsAccuracy='動作辨識率';t.statsOverallAccuracy='可接受動作辨識率';t.modePushFold='單挑SB Push/Fold';t.modeAllStreet='翻牌後探索'}applyStaticI18n();const m=new URLSearchParams(location.search).get('mode');if(['RFI','DEFEND','FACING_3BET','ALL_STREET','PUSH_FOLD','CUSTOM'].includes(m)){changeMode(m,true);setActiveTab('practice')}});

normalizeActionFrequencies=function(f,fallback='Fold'){const v=ACTION_FREQUENCY_ORDER.map(a=>Math.max(0,Number(f?.[a])||0)),total=v.reduce((a,b)=>a+b,0),out={};if(!total){ACTION_FREQUENCY_ORDER.forEach(a=>out[a]=a===fallback?100:0);return out}const raw=v.map(n=>n/total*100),base=raw.map(Math.floor),order=raw.map((n,i)=>({i,r:n-base[i]})).sort((a,b)=>b.r-a.r||a.i-b.i);for(let i=0,left=100-base.reduce((a,b)=>a+b,0);i<left;i++)base[order[i].i]++;ACTION_FREQUENCY_ORDER.forEach((a,i)=>out[a]=base[i]);return out};const SSValidate=validateCustomDrill;validateCustomDrill=function(d){const r=SSValidate(d),e=[...r.errors];if(d){for(const key of['villainPosition','openerPosition'])if(d.heroPosition&&d[key]&&d.heroPosition===d[key]&&!isDrillRandomValue(d.heroPosition))e.push('positions-must-differ');if(d.threeBetSizeBb&&d.openSizeBb&&!isDrillRandomValue(d.openSizeBb)&&+d.threeBetSizeBb<2*(+d.openSizeBb)-1)e.push('illegal-minimum-reraise');if(d.threeBetSizeBb&&d.effectiveStackBb&&+d.threeBetSizeBb>+d.effectiveStackBb)e.push('raise-exceeds-stack')}return{valid:!e.length,errors:[...new Set(e)]}};
